?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Studio admin | Crenova</title><link href="https://fonts.googleapis.com/css2?family=DM+Mono&family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Playfair+Display:ital,wght@0,500;1,500&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?= url('assets/css/style.css') ?>"><link rel="stylesheet" href="<?= url('assets/css/additions.css') ?>"><link rel="stylesheet" href="<?= url('assets/css/bright-theme.css') ?>"><script src="<?= url('assets/js/admin-blogs.js') ?>" defer></script></head>
<body class="admin-body"><aside class="admin-sidebar"><a class="brand brand-light" href="<?= url() ?>"><img src="<?= url('assets/images/crenova-mark.svg') ?>" alt=""><span>CRENOVA<br><em>STUDIO</em></span></a><span class="admin-label">Studio management</span><nav><a class="<?= $section === 'dashboard' ? 'active' : '' ?>" href="<?= url('admin') ?>">Overview</a><?php foreach ($labels as $key => $label): ?><a class="<?= $section === $key ? 'active' : '' ?>" href="<?= url('admin/' . $key) ?>"><?= e($label) ?></a><?php endforeach; ?></nav><form method="post"><input type="hidden" name="action" value="logout"><?= csrf_field() ?><button>Sign out →</button></form></aside>
