<?php if ($section === 'dashboard'): $stats=['projects'=>count(AdminResource::rows('projects')),'products'=>count(AdminResource::rows('products')),'bookings'=>count(AdminResource::rows('bookings')),'messages'=>count(AdminResource::rows('messages')),'estimates'=>count(AdminResource::rows('estimates'))]; ?><section class="admin-stats"><?php foreach ($stats as $key => $value): ?><article><span><?= e(ucfirst($key)) ?></span><b><?= e((string) $value) ?></b><small>Manage →</small></article><?php endforeach; ?></section><section class="admin-welcome"><span class="eyebrow lime">Control centre</span><h2>Your studio, in one <i>clear view.</i></h2><p>Use the navigation to add new portfolio work, update services and products, review booking requests, and respond to enquiries. Changes go live as soon as they’re saved.</p></section>
<?php elseif ($section === 'bookings'): ?><section class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Service</th><th>When</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach (AdminResource::rows('bookings') as $row): ?><tr><td><?= e($row['name'] ?? '') ?><small><?= e($row['email'] ?? '') ?></small></td><td><?= e($row['service'] ?? '') ?></td><td><?= e(($row['booking_date'] ?? '') . ' ' . ($row['booking_time'] ?? '')) ?></td><td><span class="status"><?= e($row['status'] ?? 'pending') ?></span></td><td><form method="post" class="status-form"><input type="hidden" name="action" value="admin_booking_status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($row['id']) ?>"><select name="status"><option>pending</option><option>approved</option><option>rejected</option><option>rescheduled</option><option>completed</option></select><button>Save</button></form></td></tr><?php endforeach; ?></tbody></table></section>
