<?php elseif ($section === 'estimates'): ?><section class="message-list"><?php foreach (AdminResource::rows('estimates') as $row): ?><article><div><b><?= e($row['name'] ?? '') ?></b><span><?= e($row['email'] ?? '') ?> · <?= e($row['phone'] ?? '') ?></span></div><h3>Estimate (<?= e($row['created_at'] ?? '') ?>)</h3><pre style="white-space:pre-wrap"><?= e($row['message'] ?? '') ?></pre></article><?php endforeach; ?></section>
<?php else: $rows = AdminResource::rows($section); ?><div class="admin-resource-head"><p><?= count($rows) ?> items</p><button class="button primary" data-open-modal>New <?= e(rtrim($labels[$section], 's')) ?> <b>+</b></button></div><section class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Title</th><th>Category</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><b><?= e($row['title'] ?? $row['name'] ?? $row['customer_name'] ?? 'Untitled') ?></b><small><?= e($row['slug'] ?? $row['description'] ?? '') ?></small></td><td><?= e($row['category'] ?? $row['role'] ?? $row['status'] ?? '—') ?></td><td><?= e($row['created_at'] ?? 'Recently') ?></td><td><a class="inline-link" href="<?= url('admin/' . $section . '?edit=' . $row['id']) ?>">Edit</a><form method="post" onsubmit="return confirm('Delete this item?')"><input type="hidden" name="action" value="admin_delete"><?= csrf_field() ?><input type="hidden" name="table" value="<?= e($section) ?>"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="delete-button">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></section><dialog class="admin-modal"><form method="post" enctype="multipart/form-data"><div class="modal-head"><h2>New <?= e(rtrim($labels[$section], 's')) ?></h2><button type="button" data-close-modal>×</button></div><input type="hidden" name="action" value="admin_save"><input type="hidden" name="resource" value="<?= e($section) ?>"><?= csrf_field() ?><?php foreach ($fields[$section] as $name => $label): ?><label><?= e($label) ?><?php if (in_array($name, ['description','content','excerpt','quote','meta_description','address','items'], true)): ?><textarea name="<?= e($name) ?>" rows="3"></textarea><?php else: ?><input name="<?= e($name) ?>"><?php endif; ?></label><?php endforeach; ?><?php if (in_array($section, ['projects','products'], true)): ?><label>Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><?php endif; ?><button class="button primary">Save item <b>↗</b></button></form></dialog><?php endif; ?></main><script src="<?= url('assets/js/app.js') ?>" defer></script></body></html>
